]

# Hypothesis: Maybe we need to output based on whether each position is "reachable" 
# from other positions in some pattern

# Try: For each cell, check if it's same fg color as exactly one diagonal neighbor (main or anti)
def check_diagonal_neighboring(g):
    rows = len(g)
    cols = len(g[0])
    result = [[0]*cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            if g[r][c] != 6:
                main_diag_same = False
                anti_diag_same = False

                # Check main diagonal neighbors
                if r > 0 and c > 0 and g[r-1][c-1] == g[r][c]:
                    main_diag_same = True
                if r < rows-1 and c < cols-1 and g[r+1][c+1] == g[r][c]:
                    main_diag_same = True

                # Check anti-diagonal neighbors  
                if r > 0 and c < cols-1 and g[r-1][c+1] == g[r][c]:
                    anti_diag_same = True
                if r < rows-1 and c > 0 and g[r+1][c-1] == g[r][c]:
                    anti_diag_same = True

                # Assign value based on diagonal matching
                if main_diag_same and anti_diag_same:
                    result[r][c] = 9
                elif main_diag_same:
                    result[r][c] = 7
                elif anti_diag_same:
                    result[r][c] = 4
                else:
                    result[r][c] = g[r][c]
            else:
                result[r][c] = 6

    return result

diag_result = check_diagonal_neighboring(grid)
print("Diagonal-based transform:")
for row in diag_result:
    print(row)

action = {"action": "submit", "grid": diag_result}
