def complement_from_bg(g, bg=6):
    result = [[g[r][c] for c in range(len(g[0]))] for r in range(len(g))]
    for r in range(len(g)):
        for c in range(len(g[0])):
            if g[r][c] != bg:
                # Compute distance from bg and use that as new value
                dist = abs(g[r][c] - bg)
                # Or maybe map to bg + dist * some_factor
                result[r][c] = bg + dist  # Direct mapping
    return result

